const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    var aswanPt = ee.Geometry.Point([32.8773, 23.9725]);
    var gerdPt = ee.Geometry.Point([35.0930, 11.2150]);
    var bufferMeters = 10000; // 10 km buffer for both
    var aswan = aswanPt.buffer(bufferMeters);
    var gerd = gerdPt.buffer(bufferMeters);
    var start = '2016-01-01';
    var end = '2016-12-31';

    // 2. Data Acquisition & Check with fallbacks
    var img = null;
    var datasetUsed = null;

    var annualV21 = ee.ImageCollection('NOAA/VIIRS/DNB/ANNUAL_V21').filterDate(start, end);
    var annualCount = annualV21.size().getInfo();
    console.log(`Annual V21 2016 Images: ${annualCount}`);
    if (annualCount > 0) {
      img = annualV21.first().select('avg_rad');
      datasetUsed = 'Annual V21 2016';
    } else {
      var monthlyV21 = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V21').filterDate(start, end);
      var monthlyV21Count = monthlyV21.size().getInfo();
      console.log(`Monthly V21 2016 Images: ${monthlyV21Count}`);
      if (monthlyV21Count > 0) {
        img = monthlyV21.median().select('avg_rad');
        datasetUsed = 'Monthly V21 Median 2016';
      } else {
        var monthlyV1 = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG').filterDate(start, end);
        var monthlyV1Count = monthlyV1.size().getInfo();
        console.log(`Monthly V1 (VCMSLCFG) 2016 Images: ${monthlyV1Count}`);
        if (monthlyV1Count > 0) {
          img = monthlyV1.median().select('avg_rad');
          datasetUsed = 'Monthly V1 Median 2016';
        } else {
          console.log('No images found for 2016 in any dataset.');
          console.log('C1');
          return;
        }
      }
    }
    console.log(`Using dataset: ${datasetUsed}`);

    // 3. Processing: compute mean and valid pixel count
    var reducer = ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true});
    var aswanDict = img.reduceRegion({
      reducer: reducer,
      geometry: aswan,
      scale: 1000,
      maxPixels: 1e9,
      bestEffort: true
    }).getInfo();
    var gerdDict = img.reduceRegion({
      reducer: reducer,
      geometry: gerd,
      scale: 1000,
      maxPixels: 1e9,
      bestEffort: true
    }).getInfo();

    var aswanMean = aswanDict ? aswanDict.avg_rad_mean : null;
    var aswanCount = aswanDict ? aswanDict.avg_rad_count : 0;
    var gerdMean = gerdDict ? gerdDict.avg_rad_mean : null;
    var gerdCount = gerdDict ? gerdDict.avg_rad_count : 0;

    // 4. Validation
    console.log(`Aswan px: ${aswanCount}, mean(rad): ${aswanMean}`);
    console.log(`GERD px: ${gerdCount}, mean(rad): ${gerdMean}`);

    if ((aswanCount === 0) || (gerdCount === 0)) {
      console.log('No valid pixels after processing for one or both regions.');
      console.log('C2');
      return;
    }
    if (
      aswanMean === null || gerdMean === null ||
      !isFinite(aswanMean) || !isFinite(gerdMean) ||
      aswanMean < 0 || gerdMean < 0 || aswanMean > 1e5 || gerdMean > 1e5
    ) {
      console.log('Calculation produced invalid values.');
      console.log('C3');
      return;
    }

    // 5. Calculation & Final Answer
    var diff = aswanMean - gerdMean;
    console.log(`Diff (Aswan - GERD): ${diff}`);
    if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
